-- Learnova · main-site materials (written by build_site.py). Safe to run again after adding lessons.
begin;
on conflict (path) do update set lesson_id = excluded.lesson_id, title = excluded.title, kind = excluded.kind, subject = excluded.subject, level = excluded.level, unit = excluded.unit, sort = excluded.sort;
delete from public.class_materials cm using public.classes c where c.id = cm.class_id and c.owner_kind = 'main';
) v(slug, path, sort) join public.classes c on coalesce(c.site_slug, c.follows) = v.slug and c.owner_kind = 'main' on conflict do nothing;
commit;
select (select count(*) from public.materials) as materials, (select count(*) from public.class_materials) as class_links;
